export type InlinePart =
  | { readonly type: "text"; readonly text: string }
  | { readonly type: "note" | "warning" | "key"; readonly text: string }
  | { readonly type: "route"; readonly text: string; readonly target: string };

function unescapeText(value: string): string {
  let output = "";
  for (let i = 0; i < value.length; i += 1) {
    if (value[i] === "\\" && i + 1 < value.length) {
      output += value[++i];
    } else {
      output += value[i];
    }
  }
  return output;
}

function separatorIndex(value: string): number {
  for (let i = 0; i < value.length; i += 1) {
    if (value[i] === "\\") {
      i += 1;
    } else if (value[i] === "|") {
      return i;
    }
  }
  return -1;
}

export function decodeInlineNotes(input: string): InlinePart[] {
  const result: InlinePart[] = [];
  let plain = "";
  const flush = (): void => {
    if (plain.length > 0) {
      result.push({ type: "text", text: plain });
      plain = "";
    }
  };

  for (let i = 0; i < input.length; ) {
    if (input[i] === "\\") {
      if (i + 1 < input.length) plain += input[++i];
      else plain += "\\";
      i += 1;
      continue;
    }
    if (!input.startsWith("{{", i)) {
      plain += input[i++];
      continue;
    }

    let end = i + 2;
    while (end < input.length && !input.startsWith("}}", end)) {
      if (input[end] === "\\" && end + 1 < input.length) end += 2;
      else end += 1;
    }
    if (end >= input.length) {
      plain += input.slice(i);
      break;
    }

    const raw = input.slice(i + 2, end);
    const colon = raw.indexOf(":");
    const tag = colon < 0 ? "" : raw.slice(0, colon);
    const payload = colon < 0 ? "" : raw.slice(colon + 1);
    if (tag === "note" || tag === "warning" || tag === "key") {
      flush();
      result.push({ type: tag, text: unescapeText(payload) });
    } else if (tag === "route") {
      const split = separatorIndex(payload);
      if (split < 0) {
        plain += input.slice(i, end + 2);
      } else {
        flush();
        result.push({
          type: "route",
          text: unescapeText(payload.slice(0, split)),
          target: unescapeText(payload.slice(split + 1)),
        });
      }
    } else {
      plain += input.slice(i, end + 2);
    }
    i = end + 2;
  }
  flush();
  return result;
}
